mapper.select:
select touch_id, task_id, agent_code, target_type, target_id, channel, category, status, reason, content_ref, create_time
from abr_touch_log

    and agent_code = #{agentCode}
    and target_type = #{targetType}
    and target_id = #{targetId}
    and channel = #{channel}
    and category = #{category}
    and status = #{status}

        and create_time >= cast(#{params.beginTime} as date)


        and create_time < cast(#{params.endTime} as date) + interval '1 day'


order by touch_id desc

select agent_code as "agentCode", count(*) as "count" from abr_touch_log
where category = 'marketing' and status = 'sent' and create_time >= #{since}
group by agent_code
